"""Entrega das comparações anuais por orçamento sigiloso/não sigiloso."""
from pathlib import Path
import json,sys
import pandas as pd
import numpy as np
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[1]
sys.path.insert(0,str(ROOT/'analise/painel_efeitos_fixos_20261116'))
from planilha import xlsx
def num(x,n=2):
    if x is None or not np.isfinite(x):return '—'
    return f'{x:,.{n}f}'.replace(',','X').replace('.',',').replace('X','.')
def pv(x):return '—' if x is None else '<0,0001' if x<.0001 else num(x,4)
def ci(v,n=2):return '—' if v is None else '['+num(v[0],n)+'; '+num(v[1],n)+']'
def tab(rows):return '\n'.join(['| '+' | '.join(map(str,rows[0]))+' |','|'+'|'.join(['---']*len(rows[0]))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows[1:]])
def sheet(df):return [list(df.columns)]+[[None if pd.isna(v) else v.item() if isinstance(v,np.generic) else v for v in row] for row in df.itertuples(index=False,name=None)]
def main():
    res=json.loads((OUT/'resultados.json').read_text(encoding='utf-8'));cov=pd.read_csv(OUT/'cobertura_estimado.csv');samples=pd.read_csv(OUT/'amostras.csv');audit=pd.read_csv(OUT/'auditoria_extremos_indice.csv');valid=json.loads((OUT/'validacao_final.json').read_text(encoding='utf-8'));classif=json.loads((OUT/'classificacao.json').read_text(encoding='utf-8'))
    labels={'A':'Log do preço','B':'Desconto (%)','C':'Preço/mediana anual'};out=[];descr=[];conc=[]
    for name,r in res.items():
        row={'Analise':name,'Familia':r['familia'],'Sigilo':r['sigilo'],'Orcamento':'Sigiloso' if r['sigilo'] else 'Não sigiloso','Desfecho':labels[r['codigo']],'Estimavel':r['estimavel']}
        if not r['estimavel']:out.append(row);continue
        c=r['codigo'];s=100 if c=='B' else 1;i=r['infer_duplo'];b=r['bootstrap'];a=r['descritivas']['0'];f=r['descritivas']['1'];I=i['ic95'];BI=b.get('ic_basico');P=b.get('ic_percentil')
        row.update({'Itens A':a['itens'],'Itens AF':f['itens'],'Itens total':r['itens'],'Pregoes':r['pregoes'],'Orgaos A':a['orgaos'],'Orgaos AF':f['orgaos'],'Orgaos distintos':r['orgaos'],'CATMAT':r['catmats'],'Produtos':r['produtos'],'Estratos anuais':r['estratos'],'Media A padronizada':r['media_A']*s,'Media AF padronizada':r['media_AF']*s,'Diferenca AF-A':r['diferenca']*s,'Unidade':'p.p.' if c=='B' else 'log' if c=='A' else 'indice','EP':i['ep']*s if i['ep'] is not None else None,'t':i['t'],'gl':i['gl'],'IC95 inferior':I[0]*s if I else None,'IC95 superior':I[1]*s if I else None,'p nominal':i['p'],'p Holm seis':r['p_holm6'],'p Holm trio':r['p_holm3'],'Significativo 5% seis':r['p_holm6']<.05,'p so orgao':r['infer_orgao']['p'],'p bootstrap':b.get('p'),'p bootstrap Holm seis':r['p_bootstrap_holm6'],'p bootstrap Holm trio':r['p_bootstrap_holm3'],'Bootstrap IC basico inferior':BI[0]*s if BI else None,'Bootstrap IC basico superior':BI[1]*s if BI else None,'Bootstrap IC percentil inferior':P[0]*s if P else None,'Bootstrap IC percentil superior':P[1]*s if P else None,'Bootstrap estratos retidos medio':b.get('fracao_media_estratos_retidos'),'Bootstrap replicas validas':b['replicacoes_validas'],'Bootstrap recalcula referencia':r['bootstrap_recalcula_referencia']})
        if c=='A':row.update({'Diferenca geometrica %':100*np.expm1(r['diferenca']),'IC95 geometrico inferior %':100*np.expm1(I[0]) if I else None,'IC95 geometrico superior %':100*np.expm1(I[1]) if I else None})
        out.append(row)
        for k,mode in [('0','Aberto'),('1','Aberto-Fechado')]:
            descr.append({'Analise':name,'Sigilo':r['sigilo'],'Modo':mode,'Escala':'proporcao' if c=='B' else c,**r['descritivas'][k]});conc.append({'Analise':name,'Sigilo':r['sigilo'],'Modo':mode,**r['concentracao'][k]})
    df=pd.DataFrame(out);de=pd.DataFrame(descr);co=pd.DataFrame(conc);principal=df[df.Familia.eq('principal')]
    for name,data in [('todas_estimativas.csv',df),('descritivas.csv',de),('concentracao.csv',co)]:data.to_csv(OUT/name,index=False,sep=';',encoding='utf-8-sig')
    metodo=[['Campo','Definição'],['Fonte','Extração preservada dos testes de médias anteriores, proveniente de PNCP-Automation/dados/pncp.db. Hashes e metadados conferidos; nova auditoria direta de registros.'],['Sigilo','Flag do item: 0 não sigiloso, 1 sigiloso. Desconhecidos excluídos sem imputação.'],['Tempo','Ano de abertura, tanto nos estratos quanto na referência. Coorte até abril de 2026; 2026 parcial.'],['Recorrência','Mantida a elegibilidade anterior com recorrência em meses; isso não é controle mensal na estimação anual.'],['Comparação','A versus AF dentro de cada grupo de sigilo; mesmo produto/ano/UF; peso igual por estrato.'],['Desconto','1-P/R com R positivo/finito em ambos os grupos. Sigilo=1 não implica R ausente no snapshot.'],['Benchmark','Mesmo produto/ano/UF; mediana de medianas por pregão; ambos os grupos de sigilo nos doadores; todo CNPJ-alvo excluído; mínimo 5 pregões e 2 outros CNPJs.'],['Teste','Bilateral de médias padronizadas; erros com agrupamento CNPJ e CATMAT; t com correção finita.'],['Holm','Seis testes principais: 3 desfechos x 2 grupos. Também exportado Holm por trio. ICs individuais.'],['Bootstrap','1999 sorteios de CNPJ; recálculo de medianas; perda de suporte registrada; complementar.'],['Limites','Associações; produto apenas aproximadamente equivalente; dependência intranual não absorvida; disponibilidade seletiva de R; estimado/flag do snapshot; referência pública, não preço externo certificado.']]
    abas={'Principal':sheet(principal),'Todos 30 testes':sheet(df),'Amostras':sheet(samples),'Cobertura estimado':sheet(cov),'Descritivas':sheet(de),'Concentracao':sheet(co),'Extremos indice':sheet(audit),'Diagnostico estimado':sheet(pd.read_csv(OUT/'diagnostico_estimados.csv')),'Composicao ano':sheet(pd.read_csv(OUT/'composicao_ano.csv')),'Metodologia':metodo}
    xlsx(OUT/'resultados_completos.xlsx',abas)
    indexed=df.set_index('Analise');text=[]
    text.append('**Testes de médias por sigilo do orçamento, com controle anual — 17/11/2026**\n')
    text.append('Os testes foram refeitos separando orçamento não sigiloso (flag 0) e sigiloso (flag 1), usando ANO no lugar de mês em todos os estratos de comparação e nas medianas de referência. São testes de associação entre modos dentro de cada grupo de sigilo, não estimativas causais do modo ou do sigilo.\n')
    text.append('**Fonte e preservação da amostra.** Reutilizada a extração íntegra de `PNCP-Automation/dados/pncp.db` dos testes imediatamente anteriores, conferida por hashes e metadados; '+str(valid['itens_SQLite'])+' registros foram novamente conferidos diretamente no SQLite, incluindo flag de sigilo, preços, estimados e extremos. Não é uma nova coleta. Mantidos pregão eletrônico, material, Homologado, Menor preço, A/AF, coorte madura, produto/apresentação e recorrência. O filtro de recorrência herdado conta compras em meses distintos, mas não há controle mensal nos testes. Classes principais: 6505/7510/7530/7930/8540; outras classes na sensibilidade ampliada. Fonte Dados Abertos/Compras.gov.br, não todas as plataformas PNCP.\n')
    text.append('**Classificação e disponibilidade do estimado.** Houve '+str(classif['desconhecidos_excluidos'])+' itens de sigilo desconhecido na população recorrente. Há '+num(classif['pregoes_com_ambos_sigilos_no_recorte'],0)+' pregões com itens nas duas classificações no recorte ampliado; a separação é por item. Isso não autoriza inferir uma política uniforme de sigilo por pregão.\n')
    rr=[['Orçamento','Modo','Itens prioritários antes do suporte','R positivo/finito','Cobertura de R']]
    for z in cov[cov.populacao.eq('prioritario')].itertuples():rr.append(['Sigiloso' if z.sigilo else 'Não sigiloso','AF' if z.modo else 'A',num(z.itens,0),num(z.estimado_valido,0),num(100*z.cobertura_estimado)+'%'])
    text.append(tab(rr)+'\n')
    text.append('O desconto dos sigilosos utiliza os estimados positivos disponíveis no snapshot, diferentemente da execução anterior que exigia sigilo falso. Não foi imputado preço estimado. A flag e o valor observado não comprovam quando o orçamento se tornou público nem se o estimado foi revisado depois da disputa.\n')
    text.append('**Comparação e inferência.** Dentro de cada grupo, médias padronizadas para a mesma composição de produto×ano×UF, com peso igual por estrato e por modo dentro do estrato. Produto=CATMAT+unidade/apresentação+PDM+descrição resumida. Teste bilateral equivalente à regressão ponderada com interceptos de estrato e AF, erros robustos com agrupamentos CNPJ/CATMAT, correção finita e distribuição t. Não se exige normalidade ou variâncias iguais entre itens; a confiabilidade depende do número e da informação dos grupos. A multiplicidade principal é Holm nos SEIS testes; a planilha também inclui Holm por trio. ICs são individuais.\n')
    rr=[['Orçamento','Desfecho','Itens A','Itens AF','Total','Pregões','Órgãos','Estratos anuais']]
    for _,z in principal.iterrows():rr.append([z.Orcamento,z.Desfecho,*[num(z[k],0) for k in ['Itens A','Itens AF','Itens total','Pregoes','Orgaos distintos','Estratos anuais']]])
    text.append(tab(rr)+'\n')
    for sig in [0,1]:
        text.append('**Resultados: orçamento '+('sigiloso' if sig else 'não sigiloso')+'.**\n')
        rr=[['Desfecho','Média A','Média AF','Diferença AF−A','IC95%','p nominal','p Holm seis','Signif. 5%']]
        for code in ['A','B','C']:
            z=indexed.loc[f'principal_s{sig}_{code}'];dec=4 if code=='A' else 2
            rr.append([labels[code],num(z['Media A padronizada'],dec),num(z['Media AF padronizada'],dec),num(z['Diferenca AF-A'],dec)+' '+z.Unidade,ci([z['IC95 inferior'],z['IC95 superior']],dec),pv(z['p nominal']),pv(z['p Holm seis']),'Sim' if z['Significativo 5% seis'] else 'Não'])
        text.append(tab(rr)+'\n')
        z=indexed.loc[f'principal_s{sig}_A'];text.append('Para preço, Δlog='+num(z['Diferenca AF-A'],5)+', EP='+num(z.EP,5)+', t='+num(z.t,3)+', gl='+num(z.gl,0)+'. A transformação 100×[exp(Δ)−1] resulta em **'+num(z['Diferenca geometrica %'])+'%**, IC95% '+ci([z['IC95 geometrico inferior %'],z['IC95 geometrico superior %']])+'.\n')
    text.append('O desconto é apresentado em %, com diferença em pontos percentuais; o índice P/M está em nível, e sua diferença não é percentual. Os estratos e produtos dos dois grupos podem diferir. **Significância em um grupo e ausência dela no outro não constituem teste de diferença entre grupos.** Não foi estimado um efeito causal da interação modo×sigilo.\n')
    text.append('**Referência anual e valores extremos.** M é a mediana das medianas por pregão no mesmo produto/ano/UF, fora de TODO o CNPJ-alvo, com pelo menos cinco pregões de dois outros CNPJs. Doadores incluem A/AF e os dois grupos de sigilo conhecidos para manter referência comum. É benchmark de compras públicas, não preço externo certificado de mercado, e pode conter compras posteriores à licitação dentro do ano. A inferência analítica do índice é condicional à referência; o bootstrap a recalcula.\n')
    rr=[['Sigilo','ID do item','CATMAT','Preço P','Mediana M','P/M','Unidade registrada','Quantidade']]
    for sig,h in audit.groupby('sigilo'):
        z=h.loc[h.relativo.idxmax()];rr.append(['Sim' if sig else 'Não',int(z.id),int(z.cod_item_catalogo),num(z.valor_unitario_resultado),num(z.mediana,4),num(z.relativo),z.unidade_medida,num(z.quantidade,0)])
    text.append(tab(rr)+'\n')
    text.append('Os valores extremos foram confirmados no cadastro SQLite. Isso não certifica que o preço e a unidade física sejam comparáveis: pode haver globalização de quantidades, apresentação efetiva diferente, registro inadequado ou outra condição. Não foi atribuído diagnóstico sem documento e não houve exclusão por magnitude. As médias do índice estão dominadas pelas caudas, e seus sinais opostos entre grupos não sustentam conclusão de superioridade de um modo. Auditoria e análise de influência estão anexadas.\n')
    text.append('**Bootstrap complementar.** 1.999 sorteios de órgãos, comuns aos dois grupos. Recalculados médias e benchmarks de C; referências com suporte insuficiente e estratos sem ambos os modos ficam ausentes na replicação. Essa renormalização muda a composição: o bootstrap é diagnóstico complementar.\n')
    rr=[['Sigilo','Desfecho','p bootstrap','p Holm seis bootstrap','IC95 básico','Estratos retidos em média']]
    for _,z in principal.iterrows():rr.append([z.Orcamento,z.Desfecho,pv(z['p bootstrap']),pv(z['p bootstrap Holm seis']),ci([z['Bootstrap IC basico inferior'],z['Bootstrap IC basico superior']],4 if z.Unidade=='log' else 2),num(100*z['Bootstrap estratos retidos medio'])+'%'])
    text.append(tab(rr)+'\n')
    text.append('**Distribuições e concentração.** DP, quantis, assimetria/curtose e médias brutas constam na planilha. Para log do preço, a participação dos dez maiores órgãos nos pesos AF é '+num(100*res['principal_s0_A']['concentracao']['1']['peso_top10'])+'% no grupo não sigiloso e '+num(100*res['principal_s1_A']['concentracao']['1']['peso_top10'])+'% no sigiloso. Contagem elevada de itens não equivale a muitas decisões independentes. O teste robusto não corrige erro de mensuração ou falta de comparabilidade física.\n')
    text.append('No principal não sigiloso, o bootstrap apresenta p ajustado de '+pv(res['principal_s0_A']['p_bootstrap_holm6'])+' para log do preço e '+pv(res['principal_s0_B']['p_bootstrap_holm6'])+' para desconto. Assim, a conclusão de significância do preço é sensível ao procedimento de inferência, enquanto o desconto é corroborado nessa verificação. A perda de estratos do bootstrap continua relevante e impede tratá-lo como solução definitiva.\n')
    text.append('**Sensibilidades anuais, todas registradas.** Condições de compra adiciona SRP, benefício e faixa de quantidade fator dois. Ampliado usa todas as classes. Amostra comum exige elegibilidade simultânea para os três desfechos dentro de cada sigilo. Winsor altera o desfecho pelos quantis 1/99 dentro de produto/grupo, sem substituir o principal; no seu bootstrap, referência e limites ficam fixados. Os valores-p dessas famílias são exploratórios, com Holm em seis testes por família.\n')
    rr=[['Análise','Itens A/AF','Órgãos','Diferença','IC95%','p Holm seis']]
    for _,z in df.iterrows():
        if not z.Estimavel:rr.append([z.Analise,'—','—','Não estimável','—','—']);continue
        islog=z.Unidade=='log';delta=z['Diferenca geometrica %'] if islog else z['Diferenca AF-A'];inter=[z['IC95 geometrico inferior %'],z['IC95 geometrico superior %']] if islog else [z['IC95 inferior'],z['IC95 superior']]
        rr.append([z.Analise,num(z['Itens A'],0)+'/'+num(z['Itens AF'],0),num(z['Orgaos distintos'],0),num(delta)+(' % geom.' if islog else ' '+z.Unidade),ci(inter),pv(z['p Holm seis'])])
    text.append(tab(rr)+'\n')
    text.append('**Leitura substantiva.** No principal anual, há evidência de associação entre AF, menor preço e maior desconto no grupo não sigiloso; no sigiloso, os testes principais de preço e desconto são inconclusivos. A sensibilidade com condições de compra semelhantes pode alterar essa conclusão por mudar os estratos e a população: deve ser apresentada lado a lado. Não atribuir ao sigilo a causa das diferenças, não interpretar ausência de significância como equivalência, e não tratar o índice extremo como evidência de economia ou sobrepreço causal.\n')
    text.append('**Limites do controle anual.** O ano amplia o suporte, mas não absorve sazonalidade e mudanças intranuais de preço, logística ou composição da demanda. A cobertura termina em abril de 2026, de modo que esse ano é parcial. A seleção por homologação, recorrência e presença de estimado permanece. Não há certificação independente de resultado ativo para todos os registros, nem informação completa de lotes e alterações anteriores. Classes prioritárias são proxies de bens padronizáveis. Os resultados não se estendem automaticamente a todas as plataformas PNCP ou à economia fiscal executada.\n')
    text.append('**Validação e reprodução.** '+str(valid['itens_SQLite'])+' registros conferidos diretamente no banco, '+str(valid['sigilo_0'])+' não sigilosos e '+str(valid['sigilo_1'])+' sigilosos. Conferidos classificação, preços, estimados, quantidades, modalidades e homologação. Sessenta referências reproduzidas independentemente; coeficiente e variância confrontados com WLS de dummies explícitas, inclusive 148 itens reais anuais. Medianas de reamostragem conferidas por expansão literal dos doadores. Hashes de entradas e scripts e metadados do banco preservados.\n')
    text.append('Reprodução: `validar_calculo.py`, `executar.py`, `auditar.py`, `relatar.py`, `validar_entrega.py`, com o Python portátil. Depende das extrações preservadas em `../testes_medias_20261117`; em caso de alteração do banco, reextrair antes. Entregas: `resultados_completos.xlsx`, `todas_estimativas.csv`, `descritivas.csv`, `resultados.json`, `protocolo.md`, amostras principais legíveis CSV.gz e demais amostras PKL.\n')
    (OUT/'relatorio_completo.md').write_text('\n'.join(text),encoding='utf-8')
    print(principal[['Analise','Itens A','Itens AF','Media A padronizada','Media AF padronizada','Diferenca AF-A','IC95 inferior','IC95 superior','p nominal','p Holm seis','p bootstrap Holm seis']].to_string(index=False))
if __name__=='__main__':main()
